(function(){
  'use strict';
  function array(value){return Array.isArray(value)?value:[];}
  function jaccard(a,b){a=new Set(array(a));b=new Set(array(b));if(!a.size&&!b.size)return 0;var common=0;a.forEach(function(value){if(b.has(value))common+=1;});return common/(a.size+b.size-common||1);}
  function sequenceSimilarity(live,past){var a=array(live),b=array(past),length=Math.min(a.length,b.length);if(!length)return 0;var score=0;for(var index=0;index<length;index+=1){if(a[index].direction===b[index].direction)score+=.8;if(a[index].magnitude&&b[index].magnitude&&a[index].magnitude===b[index].magnitude)score+=.2;}return score/Math.max(a.length,length);}
  function compare(live,all){if(!live||!Array.isArray(all)||!all.length)return[];var market=String(live.market||'').toLowerCase();return all.filter(function(item){return item.sessionId!==live.sessionId&&(!market||String(item.market||'').toLowerCase()===market);}).map(function(item){var marketScore=market&&String(item.market||'').toLowerCase()===market?45:0,sequence=sequenceSimilarity(live.movementSequence,item.movementSequence),patterns=jaccard(live.patternIds,item.patternIds),strategies=jaccard(live.strategyIds,item.strategyIds),score=Math.round(marketScore+sequence*35+patterns*12+strategies*8),reasons=[];if(marketScore)reasons.push('market');if(sequence)reasons.push('movement '+Math.round(sequence*100)+'%');if(patterns)reasons.push('patterns '+Math.round(patterns*100)+'%');if(strategies)reasons.push('strategies '+Math.round(strategies*100)+'%');return{similarity:Math.max(0,Math.min(100,score)),sessionId:item.sessionId,character:item.character,market:item.market,timeframe:item.timeframe,date:item.date,fateSummaryText:item.fateSummaryText,reasons:reasons,signature:item};}).sort(function(a,b){return b.similarity-a.similarity;});}
  var defaultProvider={compare:function(live,all){return Promise.resolve(compare(live,all));}};
  window.TradeJournalSessionSimilarityProvider=window.TradeJournalSessionSimilarityProvider||defaultProvider;
  window.TradeJournalSessionSignatureEngine={compare:compare,compareWithProvider:function(live,all){var provider=window.TradeJournalSessionSimilarityProvider||defaultProvider;return Promise.resolve(provider.compare(live,all));}};
}());
